import React, { useState, useEffect } from 'react';
import { Link, NavLink } from 'react-router-dom';
import { FaLeaf, FaArrowRight, FaBars, FaTimes } from 'react-icons/fa';

const navLinks = [
  { to: '/', label: 'Home' },
  { to: '/services', label: 'Services' },
  { to: '/products', label: 'Products' },
  { to: '/industries', label: 'Industries' },
  { to: '/about', label: 'About' },
  { to: '/contact', label: 'Contact' },
];

/**
 * Navbar - Fixed floating pill-shaped navbar
 * - Gains enhanced shadow on scroll
 * - Mobile hamburger with slide-down menu
 * - Active link highlighting
 */
const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const toggleMenu = () => setIsOpen((prev) => !prev);
  const closeMenu = () => setIsOpen(false);

  return (
    <nav className={`navbar-container${scrolled ? ' navbar-scrolled' : ''}`}>
      <div className="container">
        {/* Pill */}
        <div className="navbar-pill">
          {/* Logo */}
          <Link to="/" className="navbar-logo" onClick={closeMenu}>
            <div className="navbar-logo-icon">
              <FaLeaf />
            </div>
            <span>
              <span style={{ color: '#d94452' }}>Vertix</span> Solutions
            </span>
          </Link>

          {/* Desktop Links */}
          <ul className="navbar-links desktop-only">
            {navLinks.map(({ to, label }) => (
              <li key={to}>
                <NavLink
                  to={to}
                  end={to === '/'}
                  className={({ isActive }) => (isActive ? 'active' : '')}
                >
                  {label}
                </NavLink>
              </li>
            ))}
          </ul>

          {/* Desktop CTA */}
          <div className="desktop-only">
            <Link to="/contact" className="btn-primary">
              Book a Free Call
              <span className="arrow-circle">
                <FaArrowRight style={{ fontSize: '0.75rem' }} />
              </span>
            </Link>
          </div>

          {/* Mobile Hamburger */}
          <button
            className="mobile-only hamburger-btn"
            onClick={toggleMenu}
            aria-label={isOpen ? 'Close menu' : 'Open menu'}
            aria-expanded={isOpen}
          >
            {isOpen ? <FaTimes /> : <FaBars />}
          </button>
        </div>

        {/* Mobile Menu */}
        <div className={`mobile-menu mobile-only${isOpen ? ' open' : ''}`}>
          <div className="mobile-menu-inner">
            {navLinks.map(({ to, label }) => (
              <NavLink
                key={to}
                to={to}
                end={to === '/'}
                className={({ isActive }) =>
                  `mobile-menu-link${isActive ? ' active' : ''}`
                }
                onClick={closeMenu}
              >
                {label}
              </NavLink>
            ))}

            <div style={{ marginTop: '0.5rem', paddingTop: '0.75rem', borderTop: '1px solid #e5e7eb' }}>
              <Link
                to="/contact"
                className="btn-primary"
                onClick={closeMenu}
                style={{ width: '100%', justifyContent: 'space-between' }}
              >
                Book a Free Call
                <span className="arrow-circle">
                  <FaArrowRight style={{ fontSize: '0.75rem' }} />
                </span>
              </Link>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
